# ║     Rulați: python autopilot_dc_setup.py                                ║
# ║                                                                          ║
# ║   Ce face:                                                               ║
# ║     1. Creează structura de foldere a proiectului refactorizat           ║
# ║     2. Extrage toate modulele Python                                     ║
# ║     3. Verifică că toate fișierele au fost create corect                 ║
# ║     4. Afișează un raport complet                                        ║
# ╚══════════════════════════════════════════════════════════════════════════╝

import os
import sys
import json
import zlib
import base64
from pathlib import Path

# ── Payload comprimat (toate fișierele proiectului) ──────────────────────────
_PAYLOAD_B64 = """

"""

def extract_all(target_dir: Path):
    print("\n" + "="*70)
    print("  AUTOPILOT DC v3.9 — Extragere structură refactorizată")
    print("="*70)

    compressed = base64.b64decode(_PAYLOAD_B64.strip())
    raw        = zlib.decompress(compressed)
    files      = json.loads(raw.decode('utf-8'))

    created = []
    errors  = []

    for rel_path, content in files.items():
        full_path = target_dir / rel_path
        full_path.parent.mkdir(parents=True, exist_ok=True)
        try:
            full_path.write_text(content, encoding='utf-8')
            created.append(rel_path)
            print(f"  ✅ {rel_path}")
        except Exception as e:
            errors.append((rel_path, str(e)))
            print(f"  ❌ {rel_path} — {e}")

    print("\n" + "="*70)
    print(f"  RAPORT FINAL")
    print("="*70)
    print(f"  Fișiere create  : {len(created)}")
    print(f"  Erori           : {len(errors)}")

    if errors:
        print("\n  ERORI:")
        for p, e in errors:
            print(f"    ❌ {p}: {e}")
    else:
        print("\n  ✅ Extragere completă fără erori!")

    print("\n  STRUCTURA PROIECTULUI:")
    for rel in sorted(created):
        depth = rel.count(os.sep)
        indent = "  " + "  " * depth
        name = Path(rel).name
        print(f"{indent}{name}")

    print("\n" + "="*70)
    print("  PAȘI URMĂTORI:")
    print("="*70)
    print("  1. Instalați dependențele:")
    print("     pip install customtkinter pynput pyautogui openpyxl Pillow opencv-python")
    print("  2. Rulați aplicația:")
    print("     python main.py")
    print("  3. Sau rulați versiunea originală monolitică (comportament identic):")
    print("     python AutoPilot_DCv3.9.py")
    print("="*70 + "\n")


if __name__ == "__main__":
    # Rulat din folderul cu AutoPilot_DCv3.9.py → extrage în același folder
    script_dir = Path(os.path.abspath(__file__)).parent
    target     = script_dir / "autopilot_dc_project"

    print(f"\nFolder destinație: {target}")
    confirm = input("Continuați extragerea? [Y/n]: ").strip().lower()
    if confirm in ("", "y", "yes", "da", "d"):
        extract_all(target)
    else:
        print("Anulat.")
        sys.exit(0)
